my @files;
find(
  sub {
    return unless -f $_;
    return unless $_ =~ /\.md\z/;
    push @files, $File::Find::name;
  },
  $root
);

my $changed = 0;
for my $file (@files) {
  open my $in, "<:raw", $file or die "read $file: $!";
  local $/;
  my $bytes = <$in>;
  close $in;

  my $text = decode("UTF-8", $bytes, Encode::FB_CROAK);
  my $before = $text;
  for my $pair (@replacements) {
    my ($from, $to) = @$pair;
    $text =~ s/\Q$from\E/$to/g;
  }

  next if $text eq $before;
  open my $out, ">:raw", $file or die "write $file: $!";
  print {$out} encode("UTF-8", $text);
  close $out;
  print "updated $file\n";
  $changed++;
}

print "changed=$changed\n";
